  // src/prototypes/multi-attraction/styles.ts
  var CSS = `
@import url('https://fonts.googleapis.com/css2?family=Barlow:wght@400;500;600;700&family=Montserrat:wght@400&display=swap');

.ma {
  --primary: #3a6fa0;        /* eye/action/primary */
  --secondary: #092241;      /* eye/action/secondary */
  --selected: #d3e3f1;       /* eye/action/selected */
  --text: #1a1a1a;           /* eye/text/black */
  --content: #092241;        /* content/main */
  --green: #028577;          /* eye/status/green */
  --border: #e7e7e7;         /* border/neutral */
  --border-main: #ccd2d8;
  --highlight: rgba(81, 142, 200, 0.1);
  font-family: Barlow, system-ui, sans-serif;
  color: var(--text);
  background: #fff;
  width: 100%;
  height: 100%;
  position: relative;
  overflow: hidden;
  text-align: left;
}
:where(.ma) *, :where(.ma) *::before, :where(.ma) *::after { box-sizing: border-box; }
:where(.ma) img { display: block; }
:where(.ma) button { font: inherit; color: inherit; background: none; border: none; padding: 0; margin: 0; cursor: pointer; text-align: inherit; }
.ma :focus-visible { outline: 3px solid var(--primary); outline-offset: 2px; }
:where(.ma) ul { list-style: none; margin: 0; padding: 0; }
:where(.ma) h1 { font-size: 24px; font-weight: 700; line-height: normal; margin: 0; }
:where(.ma) p { margin: 0; }

.ma-screen { position: relative; width: 100%; height: 100%; display: flex; flex-direction: column; }

/* Mobile chrome */
.ma-statusbar { height: 58px; padding-top: 21px; display: flex; align-items: center; justify-content: space-between; background: #fff; flex: none; }
.ma-time { flex: 1; text-align: center; padding: 0 6px 0 16px; font: 590 17px/22px -apple-system, 'SF Pro', system-ui, sans-serif; color: #000; }
.ma-island { width: 124px; height: 10px; }
.ma-levels { flex: 1; display: flex; gap: 7px; align-items: center; justify-content: center; padding: 0 16px 0 6px; }
.ma-banner { background: var(--secondary); padding: 8px 10px; display: flex; justify-content: center; flex: none; }
.ma-banner img { object-fit: contain; }
.ma-mheader { height: 64px; padding: 12px 16px; display: flex; align-items: center; justify-content: space-between; background: #fff; flex: none; }
.ma-mheader img:first-child { object-fit: contain; object-position: left; }

/* Mobile content */
.ma-scroll { flex: 1; min-height: 0; overflow-y: auto; padding: 6px 16px 0; scrollbar-width: none; }
.ma-scroll::-webkit-scrollbar { display: none; }
.ma-intro { display: flex; flex-direction: column; gap: 8px; }
.ma-intro p { font-size: 16px; }
.ma-intro b { font-weight: 700; }
.ma-list { display: flex; flex-direction: column; gap: 16px; margin-top: 16px; }

/* Cards */
.ma-card { width: 100%; height: 100%; display: flex; gap: 8px; align-items: center; padding: 8px; border: 1px solid var(--border) !important; border-radius: 16px; background: #fff; transition: background-color .2s, border-color .2s; }
.ma-card:hover { border-color: #c9d6e3 !important; }
.ma-card.is-selected { background: var(--highlight); border-color: var(--primary) !important; }
.ma-photo { width: 100px; height: 100px; border-radius: 8px; object-fit: cover; flex: none; }
.ma-card-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.ma-name { font-size: 16px; font-weight: 700; }
.ma-desc { font-size: 12px; }
.ma-tags { display: flex; flex-wrap: wrap; gap: 4px; }
.ma-tag { background: var(--selected); color: var(--content); height: 20px; min-width: 48px; padding: 2px 4px; border-radius: 4px; font-size: 12px; line-height: 16px; white-space: nowrap; display: inline-flex; align-items: center; justify-content: center; }
.ma-card-icon { flex: none; transition: transform .15s; }
.ma-card:active .ma-card-icon { transform: scale(.9); }

.ma-compact { width: 100%; display: flex; align-items: center; justify-content: space-between; padding: 8px; border: 1px solid var(--primary) !important; border-radius: 16px; background: var(--highlight); animation: ma-in .22s ease-out; }
.ma-compact-left { display: flex; gap: 8px; align-items: center; min-width: 0; }
.ma-compact-left img { width: 36px; height: 36px; border-radius: 8px; object-fit: cover; flex: none; }
.ma-compact .ma-name { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* Summary */
.ma-sheet { position: absolute; left: 0; right: 0; bottom: 0; background: #fff; padding: 16px; display: flex; flex-direction: column; gap: 24px; border-radius: 8px 8px 0 0; filter: drop-shadow(0 -4px 2px rgba(0, 0, 0, .05)); }
.ma-summary { display: flex; flex-direction: column; gap: 12px; width: 100%; }
.ma-summary-text { display: flex; flex-direction: column; }
.ma-headline { display: flex; gap: 4px; align-items: flex-end; color: #000; white-space: nowrap; }
.ma-headline-main { font-size: 20px; font-weight: 600; line-height: 22px; }
.ma-headline-sub { font-size: 14px; }
.ma-hint { display: flex; gap: 2px; align-items: center; font-size: 14px; font-weight: 600; line-height: 20px; color: var(--primary); white-space: nowrap; }
.ma-hint-complete { color: var(--green); }
.ma-slots { display: flex; align-items: center; justify-content: space-between; width: 100%; }
.ma-slot { width: 36px; height: 36px; border-radius: 50%; object-fit: cover; flex: none; }
.ma-slot-logo { animation: ma-pop .28s cubic-bezier(.34, 1.56, .64, 1); }

/* Recommendation */
.ma-reco-block { display: flex; flex-direction: column; gap: 16px; align-items: center; width: 100%; }
.ma-reco { display: flex; gap: 8px; align-items: center; width: 100%; }
.ma-reco-img { width: 48px; height: 48px; border-radius: 8px; object-fit: cover; flex: none; }
.ma-reco-text { display: flex; flex-direction: column; width: 187px; }
.ma-eyebrow { font-size: 12px; color: var(--secondary); }
.ma-reco-name { font-size: 14px; font-weight: 700; }
.ma-reco-save { font-size: 14px; font-weight: 600; color: var(--primary); }
.ma-btn { background: var(--primary) !important; color: #fff !important; border-radius: 8px; height: 48px; display: flex; flex-direction: column; align-items: center; justify-content: center; font-size: 20px; line-height: 20px; text-transform: uppercase; text-align: center !important; transition: filter .15s; }
.ma-btn:hover { filter: brightness(1.08); }
.ma-btn:active { filter: brightness(.92); }
.ma-btn-add { flex: 1; padding: 0 16px; }
.ma-link { width: 361px; max-width: 100%; padding: 0 24px 8px !important; color: var(--primary) !important; font-size: 20px; line-height: 20px; text-transform: uppercase; text-align: center !important; }
.ma-link:hover { text-decoration: underline; }

/* Price */
.ma-price-row { display: flex; align-items: center; justify-content: space-between; width: 100%; animation: ma-in .22s ease-out; }
.ma-price { display: flex; flex-direction: column; white-space: nowrap; color: var(--content); }
.ma-price-label { font-size: 12px; }
.ma-price-value { font-size: 24px; font-weight: 500; line-height: 20px; margin: 2px 0; }
.ma-price-saved { font-size: 14px; font-weight: 500; line-height: 14px; color: var(--green); }
.ma-btn-continue { width: 230px; padding: 0 24px; }

/* Desktop */
.ma-banner-lg img { width: 90px; height: 24px; }
.ma-navbar { height: 90px; background: #fff; padding: 12px 24px; display: flex; justify-content: center; filter: drop-shadow(0 12px 6px rgba(0, 0, 0, .05)); position: relative; z-index: 1; flex: none; }
.ma-navbar-inner { flex: 1; max-width: 1280px; display: flex; align-items: center; justify-content: space-between; }
.ma-navbar-inner > img { object-fit: contain; object-position: left; }
.ma-nav-right { display: flex; align-items: center; height: 32px; }
.ma-lang { display: flex; gap: 4px; align-items: center; padding-right: 16px; font: 400 16px/24px Montserrat, system-ui, sans-serif; color: #031419; }
.ma-profile { border-left: 1px solid var(--secondary); padding-left: 16px; display: flex; width: 48px; height: 32px; align-items: center; }
.ma-dscroll { flex: 1; min-height: 0; overflow-y: auto; }
.ma-dbody { width: 1282px; margin: 52px 0 40px 80px; display: flex; gap: 80px; align-items: flex-start; }
.ma-dmain { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 32px; }
.ma-dmain .ma-intro { width: 361px; }
.ma-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }
.ma-grid li { display: flex; }
.ma-aside { width: 461px; flex: none; display: flex; flex-direction: column; gap: 24px; position: sticky; top: 0; }
.ma-module { border: 1px solid var(--border-main); border-radius: 8px; padding: 16px; }
.ma-module .ma-summary { gap: 24px; }
.ma-module .ma-summary-text { gap: 2px; }
.ma-reco-desktop { justify-content: space-between; }
.ma-reco-left { display: flex; gap: 8px; align-items: center; }
.ma-reco-desktop .ma-eyebrow { line-height: 20px; }
.ma-btn-add-desktop { padding: 0 16px; }
.ma-btn-sub { font-size: 14px; line-height: 20px; color: var(--selected); text-transform: none; }

@keyframes ma-pop { from { transform: scale(.4); opacity: 0; } to { transform: scale(1); opacity: 1; } }
@keyframes ma-in { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
.ma-rm *, .ma-rm *::before, .ma-rm *::after { animation: none !important; transition: none !important; }
`;

